const sitemapUrl = 'https://example.com/sitemap.xml';
const key = 'your-indexnow-key';
return [{ json: { sitemapUrl, key, host: sitemapUrl.replace(/^https?:\/\//i, '').split('/')[0] } }];

const cfg = $('Settings').first().json;
const xml = String($input.first().json.data || '');
const urls = [...xml.matchAll(/<loc>\s*([^<\s]+)\s*<\/loc>/gi)].map(m => m[1]);
const store = $getWorkflowStaticData('global');
const firstRun = !Array.isArray(store.seen);
const seen = new Set(firstRun ? [] : store.seen);
const fresh = urls.filter(u => !seen.has(u));
store.seen = urls;
if (firstRun || fresh.length === 0) return [];
return [{ json: { host: cfg.host, key: cfg.key, urlList: fresh.slice(0, 10000) } }];
